/* Border Companion – data file.
   Everything that changes when laws change lives here: countries, entry rules per nationality (R),
   notes (N), allowed stay lengths (DAYS), official links (AP), warnings (WARN).
   The app (index.html) loads this file fresh on every open, so editing it updates all users.
   Each text uses q(ar, en, fr, de). Keep all four languages in sync. */
const DATA_VERSION="2026-11-08";
const q=(ar,en,fr,de)=>({ar,en,fr,de});
const LANGS=["ar","en","fr","de"];

/* ---------- Shared Schengen text ---------- */
const SCH=q("منطقة شنغن: إقامة قصيرة حتى 90 يوماً خلال أي 180 يوماً. نظام الدخول والخروج الأوروبي (EES) يعمل بالكامل منذ أبريل 2026، ويسجّل البصمات وصورة الوجه بدل ختم الجواز.",
 "Schengen area: short stays up to 90 days in any 180. The EU Entry/Exit System (EES) has been fully running since April 2026 and records fingerprints and a face photo instead of a passport stamp.",
 "Espace Schengen : séjours courts jusqu'à 90 jours sur toute période de 180 jours. Le système d'entrée/sortie (EES) fonctionne pleinement depuis avril 2026 et enregistre empreintes et photo du visage à la place du tampon.",
 "Schengen-Raum: Kurzaufenthalte bis zu 90 Tage innerhalb von 180 Tagen. Das Einreise-/Ausreisesystem (EES) läuft seit April 2026 vollständig und erfasst Fingerabdrücke und Gesichtsbild statt eines Passstempels.");
const ETIAS=q("تصريح ETIAS الإلكتروني (للجنسيات المعفاة من الفيزا) لم يبدأ بعد ولا يوجد موعد رسمي. رسومه عند بدئه 20 يورو. لا تدفع لأي موقع يبيعه الآن.",
 "ETIAS (for visa-exempt nationalities) has not started and has no official date. It will cost €20 once it starts. Do not pay any site selling it now.",
 "ETIAS (pour les nationalités exemptées de visa) n'a pas encore démarré et n'a pas de date officielle. Il coûtera 20 € à son lancement. Ne payez aucun site qui le vend maintenant.",
 "ETIAS (für visumfreie Staatsangehörige) ist noch nicht gestartet und hat kein offizielles Datum. Es wird nach dem Start 20 € kosten. Zahlen Sie keiner Website, die es jetzt verkauft.");
const SCHRES=q(["الفيزا السياحية لا تسمح بالعمل أو الإقامة. للإقامة الطويلة تحتاج فيزا وطنية (D) من سفارة البلد نفسه.","تجاوز مدة 90 يوماً يُسجَّل آلياً في EES وقد يؤدي إلى غرامة ومنع دخول."],
 ["A tourist visa does not allow work or residence. Long stays need a national (D) visa from that country's embassy.","Overstaying 90 days is now recorded automatically by EES and can lead to fines and an entry ban."],
 ["Un visa touristique ne permet ni de travailler ni de résider. Un long séjour exige un visa national (D) délivré par l'ambassade du pays.","Le dépassement des 90 jours est enregistré automatiquement par l'EES et peut entraîner amende et interdiction d'entrée."],
 ["Ein Touristenvisum erlaubt weder Arbeit noch Aufenthalt. Für lange Aufenthalte brauchen Sie ein nationales Visum (D) der Botschaft des jeweiligen Landes.","Eine Überschreitung der 90 Tage wird automatisch im EES erfasst und kann Bußgeld und Einreisesperre nach sich ziehen."]);
const EUCASH=q("يجب التصريح عن 10,000 يورو أو أكثر نقداً عند دخول الاتحاد الأوروبي أو مغادرته.","You must declare €10,000 or more in cash when entering or leaving the EU.","Vous devez déclarer 10 000 € ou plus en espèces en entrant ou en sortant de l'UE.","Bargeld ab 10.000 € muss bei Ein- oder Ausreise in die bzw. aus der EU angemeldet werden.");
const EES={u:"https://travel-europe.europa.eu/ees_en",t:"travel-europe.europa.eu"};
const schEntry=q([SCH.ar,ETIAS.ar],[SCH.en,ETIAS.en],[SCH.fr,ETIAS.fr],[SCH.de,ETIAS.de]);
const plus=(base,extra)=>{const o={};LANGS.forEach(l=>o[l]=[...base[l],...(extra?extra[l]:[])]);return o};
const one=x=>{const o={};LANGS.forEach(l=>o[l]=[x[l]]);return o};
const BIGCASH=q(["صرّح عن المبالغ النقدية الكبيرة عند الدخول والخروج."],["Declare large cash amounts on entry and exit."],["Déclarez les grosses sommes en espèces à l'entrée et à la sortie."],["Große Bargeldbeträge bei Ein- und Ausreise anmelden."]);
const E112=[[q("طوارئ","Emergency","Urgences","Notruf"),"112"]];

